package com.tanidikvar.api.contact.service;
import com.tanidikvar.api.auth.service.AuthMailDelivery;import com.tanidikvar.api.auth.service.AuthMailMessage;import com.tanidikvar.api.contact.dto.ContactRequest;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.util.HtmlUtils;
@Service public class ContactService{private final AuthMailDelivery delivery;private final String from;private final String recipient;public ContactService(AuthMailDelivery delivery,@Value("${app.mail.from}")String from,@Value("${app.mail.contact-recipient}")String recipient){this.delivery=delivery;this.from=from;this.recipient=recipient;}public void send(ContactRequest request){String name=request.name().strip(),email=request.email().strip(),subject=request.subject().strip(),message=request.message().strip(),text="Gönderen: "+name+"\nE-posta: "+email+"\n\n"+message,html="<p><strong>Gönderen:</strong> "+HtmlUtils.htmlEscape(name)+"</p><p><strong>E-posta:</strong> "+HtmlUtils.htmlEscape(email)+"</p><hr><p>"+HtmlUtils.htmlEscape(message).replace("\n","<br>")+"</p>";delivery.send(new AuthMailMessage(from,recipient,"TanıdıkVar iletişim — "+subject,text,html));}}
